import{_ as a,o as s,c as i,a5 as n}from"./chunks/framework.B6tQOu6W.js";const h=JSON.parse('{"title":"Des variables en veux tu en voilà !","description":"Nous avons vu comment déclarer une balise `script`. Un code sans variable c\'est un peu comme une pizza sans olives…","frontmatter":{"description":"Nous avons vu comment déclarer une balise `script`. Un code sans variable c\'est un peu comme une pizza sans olives…"},"headers":[],"relativePath":"tp/javascript/tp1.1.md","filePath":"tp/javascript/tp1.1.md","lastUpdated":1640899309000}'),t={name:"tp/javascript/tp1.1.md"};function l(r,e,o,p,u,d){return s(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="des-variables-en-veux-tu-en-voila" tabindex="-1">Des variables en veux tu en voilà ! <a class="header-anchor" href="#des-variables-en-veux-tu-en-voila" aria-label="Permalink to &quot;Des variables en veux tu en voilà !&quot;">​</a></h1><p>Nous avons vu comment déclarer une balise <code>script</code>. Un code sans variable c&#39;est un peu comme une pizza sans olives…</p><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>Nous avons vu dans le cours que les variables pouvaient être de deux types, <code>variable</code> et <code>constante</code>, dans ce TP nous allons les utiliser.</p><h2 id="une-variable" tabindex="-1">Une variable <a class="header-anchor" href="#une-variable" aria-label="Permalink to &quot;Une variable&quot;">​</a></h2><p>Modifier le code du <a href="./tp1.html">TP précédent</a> afin de déclarer une variable :</p><div class="language-javascript vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> message </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Bonjour à tous&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Utiliser cette variable dans votre alerte.</p><h2 id="une-constante" tabindex="-1">Une constante <a class="header-anchor" href="#une-constante" aria-label="Permalink to &quot;Une constante&quot;">​</a></h2><p>En utilisant le code suivant :</p><div class="language-javascript vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nom</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Brosseau&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nom </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;valentin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Vérifier que la constante n&#39;est pas écrasée pendant le fonctionnement de votre programme.</p><h2 id="poser-une-question" tabindex="-1">Poser une question ? <a class="header-anchor" href="#poser-une-question" aria-label="Permalink to &quot;Poser une question ?&quot;">​</a></h2><p>Nous avons vu qu&#39;il était possible de déclarer une variable, mais il est également possible de poser des questions à votre utilisateur. Pour ça nous avons la fonction <code>prompt</code>, cette fonction s&#39;utilise comme ça :</p><div class="language-javascript vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prompt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Votre âge ?&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Cette fonction retourne la valeur saisie par l&#39;utilisateur, vous pouvez donc écrire :</p><div class="language-javascript vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> age </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> prompt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Votre âge ?&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="a-faire" tabindex="-1">À faire <a class="header-anchor" href="#a-faire" aria-label="Permalink to &quot;À faire&quot;">​</a></h3><p>Écrire le code permettant :</p><ul><li>De demander l&#39;âge à votre utilisateur.</li><li>Afficher la valeur avec une alerte.</li></ul><h2 id="et-si-nous-allions-plus-loin" tabindex="-1">Et si nous allions plus loin ? <a class="header-anchor" href="#et-si-nous-allions-plus-loin" aria-label="Permalink to &quot;Et si nous allions plus loin ?&quot;">​</a></h2><p>Maintenant que vous savez poser des questions et afficher des valeurs. Je vous propose de créer une machine à additionner pour ça votre programme doit :</p><ul><li>Demander la première valeur à additionner à l&#39;utilisateur</li><li>Demander la seconde valeur à l&#39;utilisateur</li><li>Réaliser l&#39;opération <code>variable1 + variable2</code> et afficher le résultat à l&#39;utilisateur (dans la console ou dans une alerte).</li></ul><p>C&#39;est à vous 😃</p><div class="tip custom-block"><p class="custom-block-title">Astuce</p><p>Il est possible en JavaSscript de « changer le type d&#39;une variable ». <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/parseInt" target="_blank" rel="noreferrer">Je vous laisse tester</a></p></div>`,25)])])}const v=a(t,[["render",l]]);export{h as __pageData,v as default};
